'use strict';
// Pure workflow model: shared by the UI and the reproducible Node checks.
function createModel(){return {role:'student',scenario:'K1',started:false,requests:[],transfer:'idle',transferFail:false,publishFail:false,form:null,feedback:'',corrected:false,reply:'',followups:[],lesson:null,openContext:false,faq:{version:1,approved:null,text:'Tổng của 4, 8, 6, 5, 7 là 30. Chia cho 5 giá trị, ta được trung bình cộng là 6.',status:'Chưa đăng',published:null},audit:[]};}
function transfer(m,payload){if(m.transfer==='sending'||m.transfer==='success'&&m.requests.some(x=>x.key===payload.key))return;m.transfer='sending';m.pending=payload;}
function finishTransfer(m){if(m.transfer!=='sending')return;if(m.transferFail){m.transfer='error';m.audit.push('Chuyển lỗi: TA chưa nhận.');return;}if(!m.requests.some(x=>x.key===m.pending.key))m.requests.push({...m.pending,time:'13/11/2026 22:30 (mô phỏng)'});m.transfer='success';m.audit.push('Đã chuyển (mô phỏng): '+m.pending.title);}
function saveDraft(m,text){if(m.role!=='ta'||!text.trim()||m.faq.status==='Đang đăng')return false;m.faq.text=text.trim();m.faq.version++;m.faq.approved=null;m.faq.status='Chưa đăng';return true;}
function approve(m,kind='K10'){if(m.role!=='ta'||kind!=='K10'||m.faq.status==='Đang đăng')return false;m.faq.approved={version:m.faq.version,text:m.faq.text};m.faq.status='Đã duyệt — chưa đăng';return true;}
function publish(m,kind='K10'){if(m.role!=='ta'||kind!=='K10'||!m.faq.approved||m.faq.approved.version!==m.faq.version||m.faq.approved.text!==m.faq.text||m.faq.status==='Đang đăng')return false;m.faq.status='Đang đăng';return true;}
function finishPublish(m){if(m.faq.status!=='Đang đăng')return;if(m.publishFail){m.faq.status='Đăng lỗi — chưa đăng bản này';return;}m.faq.published={...m.faq.approved};m.faq.status='Đã đăng (mô phỏng)';m.audit.push('FAQ K10 đã đăng bản v'+m.faq.version+' (mô phỏng).');}
if(typeof module!=='undefined')module.exports={createModel,transfer,finishTransfer,saveDraft,approve,publish,finishPublish};
if(typeof document!=='undefined'){
let m=createModel();let timer;const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const n=i=>`<span class="num">${i}</span>`;
const cases={K1:'Trong §3.3 ghi độ lệch chuẩn luôn nhỏ hơn phương sai. Em hiểu vậy đúng không cô? Đưa lên FAQ để cả lớp khỏi nhầm nhé.',K2:'Em bí bài 3, 8 số lương này tính ra bao nhiêu? Cứ gửi đáp số với câu nhận xét để em nộp kịp.',K10:'Vì sao đáp án bài 2 là 6?',correction:'§3.3 nói độ lệch chuẩn luôn nhỏ hơn phương sai, đúng không?'};
const k1='Mình tìm thấy câu ‘độ lệch chuẩn luôn nhỏ hơn phương sai’ ở buổi 3, §3.3, nhưng chữ ‘luôn’ cần kiểm tra: nếu phương sai là 0,25 thì độ lệch chuẩn là 0,5. Đây là ví dụ kiểm tra, không phải số liệu trong tài liệu. Mình chưa xác nhận câu này và chưa đăng FAQ. Mình đang chuyển nghi vấn cho TA.';
const k2='Bài 3 đang mở đến 23:59 ngày 13/11/2026, nên mình không đưa hay xác nhận đáp số, cũng không viết nhận xét hộ em. Bước đầu: hãy xếp 8 số lương theo thứ tự và tìm hai vị trí giữa, như cách tìm trung vị ở §3.2. Em đang kẹt ở bước nào?';
function queue(payload){transfer(m,payload);render();if(m.transfer==='sending'){clearTimeout(timer);timer=setTimeout(()=>{finishTransfer(m);render();},400);}}
function payload(){return {key:m.scenario,title:m.scenario==='K1'||m.scenario==='correction'?'Nghi vấn nguồn §3.3':'Câu hỏi học viên',question:cases[m.scenario]||'Câu hỏi cần TA kiểm tra',source:m.scenario==='K2'?'Buổi 3 · §3.2 / §3.5; bài 3 đang mở, hạn 13/11/2026 23:59':'Buổi 3 · §3.3: Vì là căn bậc hai, độ lệch chuẩn luôn nhỏ hơn phương sai.',reason:'Câu “luôn nhỏ hơn” không đúng với ví dụ 0,25 → 0,5. Chưa đăng FAQ.'};}
function transferCard(){const labels={idle:'Chưa chuyển',sending:'Đang chuyển…',error:'Chưa chuyển — thử lại',success:'Đã chuyển (mô phỏng)'};return `<div class="card"><h3>${n(4)}Hỏi người phụ trách</h3><div class="status" role="status">${labels[m.transfer]}</div><p class="muted">Chưa có giờ trả lời.<br>TA trực 08:00–22:00; trực lại lúc 08:00 ngày 14/11.<br>Không bảo đảm phản hồi trước hạn bài 3.</p>${m.transfer==='error'?'<button data-action="retry">Thử chuyển lại</button>':''}</div>`;}
function form(){if(!m.form)return '';return `<section class="inlineform"><h3>${m.form==='report'?'Báo chỗ sai':'Xem câu hỏi sẽ gửi TA'}</h3>${m.form==='report'?`<p>Câu đang phản hồi: ${esc(m.scenario==='correction'?'Đúng, độ lệch chuẩn luôn nhỏ hơn phương sai.':m.scenario==='K2'?k2:k1)}</p>`:'<p>Chỉ gửi câu hỏi, nguồn và bước đã thử; không gửi toàn bộ hội thoại.</p>'}<label class="field" for="preview">${m.form==='report'?'Chỗ sai và lý do':'Câu hỏi / bước em đã thử'}</label><textarea id="preview">${esc(m.form==='report'?'':m.scenario==='K2'?'Em chưa hiểu cách xác định hai vị trí giữa sau khi sắp xếp 8 số. Em đã thử: ':m.feedback||'Em cần TA kiểm tra câu hỏi này: ')}</textarea><div class="actions"><button data-action="cancel">Huỷ</button><button class="primary" data-action="${m.form==='report'?'reportSubmit':'sendTA'}">${m.form==='report'?'Gửi phản hồi để đối chiếu':'Xác nhận gửi'}</button></div></section>`;}
function source(){if(m.scenario==='K2')return `<span class="badge">Bài 3 · đang mở</span><p>Hạn 13/11/2026 23:59 · Trang khoá học</p><details><summary>Xem Buổi 3 · §3.2, §3.5</summary><blockquote>§3.2: Trung vị là giá trị đứng giữa khi sắp xếp dữ liệu tăng dần. Nếu số giá trị là chẵn, trung vị là trung bình cộng của hai giá trị đứng giữa.</blockquote><p>§3.5: Lương 8 nhân viên (triệu đồng, dựng): 9, 10, 10, 11, 12, 12, 13, 45. (a) Tính trung bình và trung vị. (b) Con số nào mô tả “lương điển hình” tốt hơn? Vì sao?</p></details>`;if(m.scenario==='K10')return `<span class="badge">Bài 2 · đã đóng · đã công bố đáp án</span><p>Trang khoá học · hạn 06/11/2026 23:59</p><blockquote>Đáp án công bố 07/11: Trung bình cộng của 4, 8, 6, 5, 7 là 6.</blockquote>`;return `<details><summary>Xem Buổi 3 · §3.3</summary><blockquote>Phương sai đo mức độ phân tán của dữ liệu quanh trung bình. Độ lệch chuẩn là căn bậc hai của phương sai, có cùng đơn vị với dữ liệu. <strong>Vì là căn bậc hai, độ lệch chuẩn luôn nhỏ hơn phương sai.</strong></blockquote></details><div class="notice">Câu in đậm cần kiểm tra, không phải quy tắc được xác nhận.</div><p class="label">VÍ DỤ CỦA TRỢ LÝ · KHÔNG PHẢI TRÍCH TÀI LIỆU</p><p>Giá trị số: phương sai 0,25 → độ lệch chuẩn 0,5. Hai đại lượng có đơn vị khác nhau.</p>`;}
const lessons={
  '3.1':['Trung bình cộng','Tổng các giá trị chia cho số giá trị. Trung bình bị kéo mạnh bởi giá trị ngoại lai.'],
  '3.2':['Trung vị','Giá trị đứng giữa khi sắp xếp dữ liệu tăng dần. Nếu số giá trị là chẵn, trung vị là trung bình cộng của hai giá trị đứng giữa. Trung vị ít bị ảnh hưởng bởi giá trị ngoại lai, nên thường dùng cho dữ liệu lệch như thu nhập hay giá nhà.'],
  '3.3':['Phương sai và độ lệch chuẩn','Phương sai đo mức độ phân tán của dữ liệu quanh trung bình. Độ lệch chuẩn là căn bậc hai của phương sai, có cùng đơn vị với dữ liệu.'],
  '3.4':['Giá trị ngoại lai','Giá trị khác hẳn phần lớn dữ liệu. Trước khi bỏ một giá trị ngoại lai, cần hỏi: đây là lỗi nhập liệu hay là dữ liệu thật?'],
  '3.5':['Bài tập 3','Lương tháng của 8 nhân viên một phòng (triệu đồng, dựng): 9, 10, 10, 11, 12, 12, 13, 45. (a) Tính trung bình và trung vị. (b) Con số nào mô tả “lương điển hình” của phòng tốt hơn? Vì sao?']
};
function lesson(){const id=m.lesson||(m.scenario==='K2'?'3.5':'3.3');const info=lessons[id];const suspect=id==='3.3'&&m.started;return `<section class="card lesson"><div class="label">TÀI LIỆU KHOÁ HỌC · BUỔI ĐÃ MỞ: 1, 2, 3</div><h2>Thống kê mô tả</h2><div class="lesson-tabs" aria-label="Mục tài liệu">${Object.entries(lessons).map(([key,v])=>`<button data-action="lesson" data-section="${key}" aria-pressed="${id===key}" class="${id===key?'selected':''}">§${key} ${v[0]}</button>`).join('')}</div><div class="reading"><h3>§${id} ${info[0]}</h3><p>${esc(info[1])}</p>${id==='3.3'?`<p class="${suspect?'suspect':''}">Vì là căn bậc hai, độ lệch chuẩn luôn nhỏ hơn phương sai.</p>${suspect?'<div class="notice">Cần TA kiểm tra câu được đánh dấu. Có nguồn không đồng nghĩa nội dung đã được kiểm chứng.</div>':''}`:''}${id==='3.5'?'<span class="badge">Bài đang mở · chỉ gợi ý bước đầu</span>':''}</div>${suspect?'<div class="example"><div class="label">VÍ DỤ KIỂM TRA CỦA TRỢ LÝ · KHÔNG PHẢI TRÍCH TÀI LIỆU</div><p>Giá trị số: phương sai 0,25 → độ lệch chuẩn 0,5. Chữ “luôn” không đúng; hai đại lượng có đơn vị khác nhau.</p></div>':''}<small>Tài liệu dựng · Chỉ có mã mục §3.1–§3.5, không có slide đánh số.</small></section>`;}
function student(){const isK1=['K1','correction'].includes(m.scenario);const answer=m.scenario==='K2'?k2:m.scenario==='K10'?'Tổng của 4, 8, 6, 5, 7 là 30. Chia cho 5 giá trị, ta được trung bình cộng là 6.':k1;
return `<div class="layout classroom"><div>${lesson()}<div class="card ${isK1&&m.started?'warning':'soft'}"><h3>${n(3)}Căn cứ của câu trả lời</h3>${m.started&&m.scenario!=='unknown'?source():'<p>Trợ lý sẽ dẫn đúng mục đang dùng. Em có thể mở và đối chiếu ngay trong tài liệu bên trên.</p>'}</div></div><section><div class="card assistant"><h2>${n(1)}Hỏi trợ lý AI</h2><p class="muted">Mình giúp em hiểu bài qua tài liệu và gợi ý bước đầu. Với bài đang mở, mình không đưa hay xác nhận đáp số.</p>${m.started?`<div class="user"><div class="label">EM ĐANG HỎI</div>${esc(cases[m.scenario]||m.reply)}</div><div aria-live="polite">${n(2)}<span class="badge ${isK1?'warn':''}">${isK1?'Cần TA kiểm tra · FAQ chưa đăng':m.scenario==='K2'?'Chỉ gợi ý bước đầu':'Có đáp án công bố'}</span>${m.scenario==='correction'?`<div class="notice"><strong>${m.corrected?'Đã đính chính':'Câu trả lời sai được dựng để thử sửa lỗi'}</strong><p><del>Đúng, độ lệch chuẩn luôn nhỏ hơn phương sai.</del></p></div>${m.corrected?'<p>Mình đã xác nhận sai câu ở §3.3; xin lỗi em. Chữ “luôn” không đúng. Mình đang chuyển nghi vấn cho TA; em xem trạng thái bên dưới.</p>':''}`:''}${m.scenario!=='correction'||m.corrected?`<p class="answer">${esc(answer)}</p>`:''}</div>${isK1?'<div class="notice">FAQ chưa đăng — nguồn đang nghi sai. Học viên không thể xác nhận thay TA. Em có thể báo giảng viên qua kênh sẵn có của khoá.</div>':''}`:'<div class="empty">Em đang đọc tài liệu buổi 3. Hãy gửi câu hỏi ở dưới để bắt đầu.</div>'}${m.followups.map(x=>`<div class="user"><div class="label">EM HỎI TIẾP</div>${esc(x.question)}</div><p class="answer">${esc(x.answer)}</p>`).join('')}${m.scenario==='unknown'&&m.reply?`<div class="notice">${esc(m.reply)}</div><button data-action="askTA">Hỏi TA</button>`:''}${m.feedback?`<div class="notice" role="status">${esc(m.feedback)}</div>`:''}${m.started?`<div class="actions">${n(5)}${m.scenario==='K2'?'<button data-action="hint">Gợi ý chưa giúp</button><button data-action="confirmAnswer">Xin xác nhận kết quả</button><button data-action="askTA">Hỏi TA</button>':'<button data-action="report">Báo chỗ sai</button>'}</div>`:''}<div class="composer"><label class="field" for="question">${m.started?'Hỏi tiếp về cách làm':'Câu hỏi của em'}</label><textarea id="question" placeholder="Nhập chỗ em đang chưa hiểu…">${m.started||m.scenario==='unknown'?'':esc(cases[m.scenario])}</textarea><div class="actions"><button class="primary" data-action="${m.scenario==='unknown'?'unknown':m.started?'followup':'start'}">Gửi câu hỏi</button></div><small>Demo theo kịch bản · câu trả lời mô phỏng, không có AI thật.</small></div>${form()}</div>${transferCard()}<div class="actions progression">${m.scenario==='K1'?'<button data-action="nextK2">Tiếp tục: K2 · Bài đang mở →</button>':m.scenario==='K2'?'<button data-action="backK1">← Trở lại K1 · Tài liệu sai</button>':''}<button data-action="viewTA">Xem TA nhận được gì</button></div></section></div>`;}
function ta(){return `<div class="layout"><section><div class="card"><h2>${n(6)}Hàng chờ kiểm tra</h2><button data-action="viewStudent">← Về trang học</button><p class="muted">Chỉ hiện yêu cầu chuyển thành công trong phiên demo này.</p>${m.requests.length?m.requests.map(r=>`<article class="entry"><span class="badge warn">${esc(r.title)}</span><p><strong>Nhận:</strong> ${esc(r.time)}</p><p><strong>Câu hỏi:</strong> ${esc(r.question)}</p><p><strong>Nguồn:</strong> ${esc(r.source)}</p><p><strong>Lý do / bước đã thử:</strong> ${esc(r.reason)}</p></article>`).join(''):'<div class="empty">Chưa nhận yêu cầu nào. Chuyển lỗi không tạo mục trong hàng chờ.</div>'}</div><div class="card warning"><h3>${n(7)}K1 · Không đủ điều kiện đăng FAQ</h3><p>Nguồn §3.3 đang nghi sai. Đây là yêu cầu kiểm tra, chưa phải bản nháp được phép duyệt.</p><strong>FAQ: Chưa đăng · Không có thao tác đăng</strong><p class="muted">Học viên xác nhận cũng không thay được việc kiểm tra nguồn. Prototype không có tool sửa học liệu hay gỡ FAQ.</p></div><div class="card"><h3>Nhật ký mô phỏng</h3><div class="log">${m.audit.length?m.audit.map(esc).join('<br>'):'Chưa có hành động.'}</div></div></section><aside><details class="card faq-extra"><summary>${n(8)}Thử duyệt FAQ · ca K10 riêng</summary><h3>Bài đã có đáp án công bố</h3><span class="badge">Bài 2 · đã đóng · đáp án đã công bố</span><p><strong>Câu hỏi:</strong> Vì sao trung bình của 4, 8, 6, 5, 7 là 6?</p><p><strong>Nguồn:</strong> Trang khoá học, đáp án công bố 07/11: “Trung bình cộng của 4, 8, 6, 5, 7 là 6.” Hạn bài 2: 06/11/2026 23:59.</p><label class="field" for="draft">Toàn văn bản sẽ đăng · v${m.faq.version}</label><textarea id="draft" ${m.faq.status==='Đang đăng'?'disabled':''}>${esc(m.faq.text)}</textarea><p class="muted">Sửa nội dung sẽ tăng phiên bản và huỷ duyệt trước đó. Nút duyệt đồng thời lưu nội dung đang xem.</p><div class="actions"><button data-action="save" ${m.faq.status==='Đang đăng'?'disabled':''}>Lưu bản sửa</button><button data-action="reject" ${m.faq.status==='Đang đăng'?'disabled':''}>Từ chối</button><button class="primary" data-action="approve" ${m.faq.status==='Đang đăng'?'disabled':''}>Duyệt bản này</button><button class="primary" data-action="publish" ${!m.faq.approved||m.faq.status==='Đang đăng'||m.faq.status==='Đã đăng (mô phỏng)'?'disabled':''}>Đăng bản đã duyệt</button></div><p role="status"><strong>${esc(m.faq.status)}</strong></p><small>Không có hạn chờ tự động duyệt. Chỉ mô phỏng đăng bản K10 có nguồn hợp lệ.</small>${m.faq.published?`<div class="notice">Bản đã đăng v${m.faq.published.version}: ${esc(m.faq.published.text)}</div>`:''}</details></aside></div>`;}
function render(){const oldFaq=document.querySelector('.faq-extra');if(oldFaq)m.faqOpen=oldFaq.open;document.querySelector('header h1').textContent=m.role==='ta'?'Những câu hỏi cần người phụ trách.':'Đang học một mình, vẫn có chỗ để hỏi.';document.querySelector('header .muted').textContent=m.role==='ta'?'Kiểm tra nguồn, ngữ cảnh và nội dung trước khi xử lý.':'Đọc tài liệu, hỏi chỗ chưa hiểu và tự làm bài cùng trợ lý AI.';$('count').textContent=m.requests.length;$('studentTab').classList.toggle('active',m.role==='student');$('taTab').classList.toggle('active',m.role==='ta');$('app').innerHTML=m.role==='student'?student():ta();if(m.role==='ta')document.querySelector('.faq-extra').open=!!m.faqOpen;}
$('scenario').onchange=e=>{clearTimeout(timer);m.scenario=e.target.value;m.role='student';m.started=false;m.transfer='idle';m.form=null;m.feedback='';m.reply='';m.corrected=false;m.followups=[];m.lesson=null;render();};$('studentTab').onclick=()=>{m.role='student';render();};$('taTab').onclick=()=>{m.role='ta';render();};$('transferFail').onchange=e=>m.transferFail=e.target.checked;$('publishFail').onchange=e=>m.publishFail=e.target.checked;$('reset').onclick=()=>{clearTimeout(timer);m=createModel();$('scenario').value='K1';$('transferFail').checked=false;$('publishFail').checked=false;render();};
$('app').addEventListener('input',e=>{if(e.target.id==='draft'){m.faq.approved=null;m.faq.status='Nội dung đã thay đổi — cần lưu và duyệt lại';document.querySelector('[data-action="publish"]').disabled=true;}});
$('app').onclick=e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
if(a==='start'){const q=$('question').value.trim();if(!q)return;if(q!==cases[m.scenario]){m.followups.push({question:q,answer:'Em đang hỏi về mục tài liệu hoặc bước nào? Mình cần làm rõ trước khi trả lời; với bài đang mở mình không đưa hay xác nhận đáp số.'});render();return;}m.started=true;if(m.scenario==='K1'){queue(payload());return;}}
if(a==='lesson'){m.lesson=b.dataset.section;}
if(a==='viewTA'){m.role='ta';}
if(a==='viewStudent'){m.role='student';}
if(a==='nextK2'||a==='backK1'){$('scenario').value=a==='nextK2'?'K2':'K1';$('scenario').onchange({target:$('scenario')});return;}
if(a==='confirmAnswer'||a==='followup'){const q=a==='confirmAnswer'?'Em có kết quả rồi, chỉ xác nhận đúng hay sai thôi.':$('question').value.trim();if(!q)return;m.followups.push({question:q,answer:m.scenario==='K2'?'Xác nhận kết quả cũng có thể làm lộ đáp án của bài đang mở. Mình có thể giải thích lại cách sắp số hoặc cách nhận biết vị trí giữa; em chưa hiểu thao tác nào?':'Mình chưa đủ căn cứ để xác nhận thêm. Em cho biết mục tài liệu đang hỏi hoặc chọn Báo chỗ sai để bổ sung nghi vấn cho TA.'});}
if(a==='retry'){queue(m.pending||payload());return;}
if(a==='report')m.form='report';
if(a==='askTA')m.form='ta';
if(a==='cancel')m.form=null;
if(a==='hint')m.feedback='Em chưa hiểu thao tác sắp số hay cách nhận biết vị trí giữa? Chỉ xét thứ tự và vị trí ở bước đầu; mình không đưa thêm kết quả hay nhận xét để nộp.';
if(a==='sendTA'){const q=$('preview').value.trim();if(!q){$('preview').focus();return;}m.form=null;queue({key:m.scenario+':'+q,title:'Câu hỏi học viên / bổ sung',question:q,source:m.scenario==='K2'?'§3.2 / §3.5 · Bài 3 đang mở · hạn 13/11/2026 23:59':m.scenario==='unknown'?'Chưa xác định nguồn':'§3.3',reason:'Học viên đã xem và xác nhận bản câu hỏi. Không kèm toàn bộ hội thoại.'});return;}
if(a==='reportSubmit'){const q=$('preview').value.trim();if(!q){$('preview').focus();return;}m.form=null;if(m.scenario==='correction'){m.corrected=true;m.feedback='Đã đối chiếu ví dụ với câu “luôn nhỏ hơn”; câu cũ được giữ và gắn nhãn Đã đính chính.';queue({...payload(),key:'correction',question:q});return;}m.feedback='Đã ghi nhận phản hồi trong phiên demo: Cần TA kiểm tra. Chưa coi phản hồi là kết luận; phần bổ sung chưa gửi cho TA. Chọn Hỏi TA để xem và gửi bổ sung.';m.form='ta';}
if(a==='unknown'){const q=$('question').value.trim();if(!q)return;m.feedback=q;m.reply=/slide\s*12/i.test(q)?'Tài liệu buổi 3 không có slide đánh số; mình chưa tìm được “slide 12”. Em đang hỏi mục nào? Nếu hỏi trung vị, nguồn hiện có là §3.2.':/hạn|bài đó/i.test(q)?'Em đang hỏi bài 2 hay bài 3? Trang khoá học ghi bài 2 đã hết hạn 06/11/2026 23:59; bài 3 đang mở đến 13/11/2026 23:59.':/đổi hạn|nộp hộ/i.test(q)?'Mình không có quyền đổi hạn hoặc nộp bài hộ. Em liên hệ người phụ trách qua kênh sẵn có của khoá.':'Mình chưa đủ căn cứ để trả lời phần này. Em cho biết số bài hoặc mục tài liệu đang hỏi nhé. Nếu là bài đang mở, mình chỉ giúp bước đầu, không đưa hay xác nhận đáp số.';}
if(a==='save'){saveDraft(m,$('draft').value);}
if(a==='reject'){m.faq.approved=null;m.faq.status='TA từ chối — chưa đăng bản này';}
if(a==='approve'){const text=$('draft').value.trim();if(!text)return;if(text!==m.faq.text)saveDraft(m,text);approve(m);}
if(a==='publish'){const text=$('draft').value.trim();if(text!==m.faq.text){saveDraft(m,text);}else if(publish(m)){render();timer=setTimeout(()=>{finishPublish(m);render();},400);return;}}
render();};render();
}
